import{_ as t,c as e,o as p,a3 as r}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"常见问题（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md","lastUpdated":1786597585000}'),o={name:"zh-CN/guide/faq.md"};function n(s,a,i,l,c,g){return p(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h1><p><strong>问：什么是 ClipboardxAI？</strong></p><p>答：ClipboardxAI 是一款面向 macOS 的智能剪贴板管理器。它会将你复制的一切内容保存为可搜索的历史记录，并让你对其执行操作——总结、翻译、整理文本，或发送给云端 AI 模型。</p><p><strong>问：支持哪些 macOS 版本？</strong></p><p>答：macOS 14 Sonoma 或更高版本，针对 Apple Silicon（M 系列）优化，同时支持 Intel。</p><p><strong>问：如何安装？</strong></p><p>答：从 <a href="/zh-CN/">Mac App Store</a>（推荐）下载，或从 <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a> 获取最新版本。详见<a href="/zh-CN/guide/installation.html">安装指南</a>。</p><p><strong>问：ClipboardxAI 免费吗？</strong></p><p>答：ClipboardxAI 是 Mac App Store 上的付费应用。购买后所有内置本地工具均已包含，无需账号。云端 AI 操作使用<em>你自己的</em>提供商 API key，费用直接支付给 AI 提供商——应用内无需额外付费。</p><p><strong>问：支持哪些 AI 提供商？</strong></p><p>答：任何 OpenAI 兼容的提供商：DeepSeek、MiniMax、Zhipu GLM、Kimi (Moonshot)、Mistral，以及本地 Ollama——外加 OpenAI、Anthropic 与 Gemini。你的 key 保存在 Keychain 中。</p><p><strong>问：它可以离线使用吗？</strong></p><p>答：可以。剪贴板历史与内置本地工具（提取链接、字数统计、压缩空行等）完全在你的 Mac 上运行，无需联网。</p><p><strong>问：我的剪贴板数据私密吗？</strong></p><p>答：你的历史记录始终留在你的设备上。云端 AI 是可选的，并且只使用你 Keychain 中的 key，将内容发送给所配置的提供商。我们从不接收或存储你的剪贴内容，也没有任何遥测。详见<a href="/zh-CN/guide/privacy.html">隐私政策</a>。</p><p><strong>问：如何添加更多操作？</strong></p><p>答：浏览 <a href="/zh-CN/marketplace/">Marketplace</a>，点击任意操作的 <strong>安装（Install）</strong>。它会通过深链接打开应用，并出现在你的 <strong>已安装（Installed）</strong> 列表中。</p><p><strong>问：如何更新应用？</strong></p><p>答：Mac App Store 版本会自动更新。对于 GitHub 版本，请下载最新版本并替换 <code>Applications</code> 中的旧应用。</p><p><strong>问：如何报告错误或请求功能？</strong></p><p>答：在 <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub 仓库</a> 上提交 issue。请附上你的 macOS 版本、应用版本与复现步骤。</p><p><strong>问：我的数据保存在哪里？</strong></p><p>答：保存在沙盒容器中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>API key 存放在系统 Keychain 中，不在此文件夹内。</p>',25)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
